[tool_call Bash] {"command":"python3 - <<'EOF'
from assignment_updates import apply_assignment_change

class FakeResp:
    def __init__(self, status, headers, body):
        self.status, self.headers, self.body = status, headers, body

class FakeSession:
    def __init__(self):
        self.calls = []
    def request(self, method, path, headers=None, body=None):
        self.calls.append((method, headers or {}))
        if method == "GET":
            return FakeResp(200, {"etag": '"e1"'}, {
                "JobCode": "A",
                "links": [{"rel": "self", "href": "http://x" + path,
                           "properties": {"changeIndicator": '"e1"'}}],
            })
        return FakeResp(200, {"etag": '"e2"'}, {
            "JobCode": "B",
            "links": [{"rel": "self", "href": "http://x" + path,
                       "properties": {"changeIndicator": '"e2"'}}],
        })

s = FakeSession()
r = apply_assignment_change(s, "W", 1, "A", changes={"JobCode": "B"}, mode="correction")
print("result_has_links =", "links" in r.item)

for bad in ["", "2026-99-99", "2026-8-1", "not-a-date", "2026-02-30", 20260801]:
    for kwargs in (
        dict(mode="update", range_start=bad),
        dict(mode="correction", range_start=bad),
        dict(mode="correction", range_start="2026-01-01", range_end=bad),
    ):
        s2 = FakeSession()
        try:
            apply_assignment_change(s2, "W", 1, "A", changes={"JobCode": "B"}, **kwargs)
            print("NOT REJECTED:", bad, kwargs)
        except ValueError:
            assert s2.calls == [], f"HTTP happened before rejection: {bad} {kwargs}"
print("all bad dates rejected locally with zero HTTP calls")
EOF","description":"Probe links retention and local date validation"}
